import React, { useEffect, useRef, useState } from 'react';

const RealtimeVoiceChat: React.FC = () => {
  const [recording, setRecording] = useState<boolean>(false);
  const [wsStatus, setWsStatus] = useState<string>('idle');
  const [lastError, setLastError] = useState<string>('');
  const [progressBytes, setProgressBytes] = useState<number>(0);
  const [lastAsrText, setLastAsrText] = useState<string>('');
  const wsRef = useRef<WebSocket | null>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const mediaStreamRef = useRef<MediaStream | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  const getTgIdString = () => {
    try {
      const fromSession = sessionStorage.getItem('tg_id');
      if (fromSession) return String(fromSession);
    } catch {}
    try {
      const wa = (window as any).Telegram?.WebApp?.initDataUnsafe?.user;
      const id = wa?.id;
      return id ? String(id) : '';
    } catch {}
    return '';
  };

  const buildWsUrl = () => {
    try {
      const proto = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
      const host = window.location.host;
      return `${proto}//${host}/api/voice/rt`;
    } catch {
      return '/api/voice/rt';
    }
  };

  const start = async () => {
    if (recording) return;
    try {
      setLastError('');
      const wsUrl = buildWsUrl();
      const ws = new WebSocket(wsUrl);
      ws.binaryType = 'arraybuffer';
      wsRef.current = ws;
      setProgressBytes(0);
      setLastAsrText('');
      setWsStatus('connecting');

      ws.onopen = async () => {
        setWsStatus('open');
        const tgId = getTgIdString();
        const startPayload = { type: 'start', lang: 'ru-RU', format: 'ogg', tg_id: tgId, mode: 'soul' };
        try { ws.send(JSON.stringify(startPayload)); } catch {}
        try {
          if (!navigator?.mediaDevices?.getUserMedia) {
            throw new Error('mediaDevices.getUserMedia недоступен в этом окружении');
          }
          const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
          mediaStreamRef.current = stream;
          const mime = (MediaRecorder as any).isTypeSupported?.('audio/ogg;codecs=opus')
            ? 'audio/ogg;codecs=opus'
            : ((MediaRecorder as any).isTypeSupported?.('audio/webm;codecs=opus') ? 'audio/webm;codecs=opus' : 'audio/webm');
          const mr = new MediaRecorder(stream, { mimeType: mime as any });
          mediaRecorderRef.current = mr;
          mr.ondataavailable = async (e: BlobEvent) => {
            try {
              if (!e.data) return;
              const buf = await e.data.arrayBuffer();
              ws.send(buf);
            } catch {}
          };
          mr.start(300);
          setRecording(true);
        } catch (e: any) {
          console.error('[RealtimeVoice] getUserMedia error', e);
          setLastError('Доступ к микрофону отклонён или недоступен. Проверьте разрешения.');
          try { ws.close(); } catch {}
        }
      };

      ws.onmessage = async (ev: MessageEvent) => {
        try {
          if (typeof ev.data === 'string') {
            const msg = JSON.parse(ev.data);
            const t = String(msg.type || '');
            if (t === 'progress') {
              const b = Number(msg.bytes || 0);
              if (!Number.isNaN(b)) setProgressBytes(b);
            } else if (t === 'asr_partial') {
              if (msg.text) setLastAsrText(String(msg.text) + ' (частично…)');
            } else if (t === 'asr_final') {
              if (msg.text) setLastAsrText(String(msg.text));
            } else if (t === 'error') {
              console.warn('[RealtimeVoiceWS] error', msg);
            }
            return;
          }
          const arr = ev.data as ArrayBuffer;
          const blob = new Blob([arr]);
          const url = URL.createObjectURL(blob);
          let el = audioRef.current;
          if (!el) {
            el = new Audio();
            el.autoplay = true;
            el.controls = false;
            audioRef.current = el;
          }
          try {
            el.src = url;
            await el.play();
          } catch (e) {
            console.warn('[RealtimeVoice] autoplay blocked', e);
          }
        } catch (e) {
          console.warn('[RealtimeVoiceWS] onmessage parse error', e);
        }
      };

      ws.onclose = () => {
        setWsStatus('closed');
        setRecording(false);
        setProgressBytes(0);
        try { mediaRecorderRef.current?.stop?.(); } catch {}
        try { mediaStreamRef.current?.getTracks()?.forEach(t => t.stop()); } catch {}
        mediaRecorderRef.current = null;
        mediaStreamRef.current = null;
      };

      ws.onerror = (ev: Event) => {
        setWsStatus('error');
        setLastError('Ошибка соединения WebSocket. Попробуйте ещё раз.');
        try { ws.close(); } catch {}
      };
    } catch (e) {
      console.error('[RealtimeVoice] start error', e);
      setLastError('Сбой запуска речи. Попробуйте ещё раз.');
      setRecording(false);
    }
  };

  const stop = async () => {
    try { mediaRecorderRef.current?.stop?.(); } catch {}
    try { mediaStreamRef.current?.getTracks()?.forEach(t => t.stop()); } catch {}
    mediaRecorderRef.current = null;
    mediaStreamRef.current = null;
    setRecording(false);
    try { wsRef.current?.send?.(JSON.stringify({ type: 'stop' })); } catch {}
    try { wsRef.current?.close?.(); } catch {}
  };

  useEffect(() => {
    return () => { try { wsRef.current?.close?.(); } catch {} };
  }, []);

  return (
    <div style={{ padding: 16 }}>
      <h2 style={{ margin: '0 0 12px 0' }}>Реал‑тайм голос</h2>
      <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 12 }}>
        <button onClick={start} disabled={recording} style={{ padding: '8px 12px' }}>▶️ Старт</button>
        <button onClick={stop} disabled={!recording} style={{ padding: '8px 12px' }}>⏹️ Стоп</button>
        {recording ? <span style={{ color: '#8E8E93' }}>принято ~{Math.round(progressBytes / 1024)} KB</span> : null}
        <span style={{ color: '#8E8E93' }}>
          {wsStatus === 'connecting' ? 'соединение...' : wsStatus === 'open' ? 'онлайн' : wsStatus === 'error' ? 'ошибка' : ''}
        </span>
      </div>
      {lastError && (
        <div style={{ marginBottom: 12, color: '#b91c1c', background: '#fee2e2', border: '1px solid #fecaca', padding: '8px 10px', borderRadius: 6, fontSize: 12 }}>
          {lastError}
        </div>
      )}
      <div style={{ minHeight: 24, color: '#8E8E93' }}>
        {lastAsrText ? (
          <span>ASR: “{lastAsrText.slice(0, 128)}{lastAsrText.length > 128 ? '…' : ''}”</span>
        ) : (
          <span>Нет распознанного текста</span>
        )}
      </div>
    </div>
  );
};

export default RealtimeVoiceChat;


